            qbdsRebateGroupLink.name(),
            fieldStr(TAMRebateGroupLink, RebateGroupId),
            fieldStr(TAMRebateTable, AccountCode),
            fieldStr(TAMRebateTable, AccountRelation),
            qbdsRebateGroupLinkCust.name(),
            fieldStr(METRebateScanSupplierTable, CustVendAccount)));

        queryRun = new QueryRun(query);
        while(queryRun.next())
        {
            TAMRebateTable              rebateTable;
            TAMRebateDate               rebateDate;
            METRebateScanSupplierTable  scanSupplierData;

            rebateTable         =   queryRun.get(tableNum(TAMRebateTable));
            scanSupplierData    =   queryRun.get(tableNum(METRebateScanSupplierTable));
            
            select firstonly rebateDate where rebateDate.RebateId == rebateTable.RebateId
                                           && rebateDate.RebateFromDate <= scanSupplierData.TransactionDate
                                           && rebateDate.RebateToDate >= scanSupplierData.TransactionDate;
            if(rebateDate)
            {
                rebateDateTrans = this.createDateTrans(rebateDealContract.RecId, rebateTable.RebateId, scanSupplierData.TransactionDate, rebateDate, transType);

                if(rebateDateTrans.RebateFromDate <= scanSupplierData.TransactionDate && rebateDateTrans.RebateToDate >= scanSupplierData.TransactionDate)
                {
                    this.createTrans(rebateDateTrans, rebateDate, scanSupplierData, toleranceQty, rebateTable.UnitId);
                }
            }
        }
        
        TAMRebateTrans              rebateTrans;

        delete_from rebateDateTrans where rebateDateTrans.RebateDeal == rebateDealContract.RecId
            notexists join rebateTrans where rebateDateTrans.RebateTransId == rebateTrans.RebateTransId;

    }

    /// <summary>
    /// Method to create Rebate transactions
    /// </summary>
    /// <param name = "_rebateDealRecId">Rebate deal Reference to transaction</param>
    /// <param name = "_rebateTableRebateId">Rebate table reference to transaction</param>
    /// <param name = "_scanSupplierTransDate">Transaction date of custom Scan data</param>
    /// <param name = "_rebateDate">TAMRebateDate table</param>
    /// <param name = "_transType">Transaction type from user interface</param>
    /// <returns>Existing or newly created rebate transaction reference</returns>
    protected TAMRebateDateTrans createDateTrans(RefRecId                   _rebateDealRecId,
                                                 TAMRebateId                _rebateTableRebateId,
                                                 TransDate                  _scanSupplierTransDate,
                                                 TAMRebateDate              _rebateDate,
                                                 TAMRebateTransactionType   _transType)
    {
        TAMRebateDateTrans          rebateDateTrans;

        select firstonly1 rebateDateTrans
            where rebateDateTrans.RebateId == _rebateTableRebateId
               && rebateDateTrans.RebateDeal == _rebateDealRecId
               && rebateDateTrans.RebateFromDate <= _scanSupplierTransDate
               && rebateDateTrans.RebateToDate >= _scanSupplierTransDate
               && rebateDateTrans.RebateTransactionType == _transType;
        if(rebateDateTrans)
        {
            return rebateDateTrans;
        }
        else
        {
            try
            {
                ttsbegin;
                rebateDateTrans.RebateFromDate              =   _scanSupplierTransDate;
                rebateDateTrans.RebateToDate                =   _scanSupplierTransDate + this.getRebateToDate(_rebateDate, _scanSupplierTransDate);

                rebateDateTrans.RebateDeal                  =   _rebateDealRecId;
                rebateDateTrans.RebateId                    =   _rebateTableRebateId;
                rebateDateTrans.RebateTransactionType       =   _transType;

                rebateDateTrans.RebateTransId               =   NumberSeq::newGetNum(NumberSeqReference::findReference(extendedTypeNum(METOrigRebateTransId))).num();//numberSeq.num();
            
                if(rebateDateTrans.validateWrite())
                {
                    rebateDateTrans.insert();
                }
                ttscommit;
            }
            catch(Exception::DuplicateKeyException)
            {
                Info("@MET:METRebateDuplicateKey");
                throw Exception::DuplicateKeyExceptionNotRecovered;
            }
            catch(Exception::Error)
            {
                Info("@MET:METRebateInsertError");
            }
            return rebateDateTrans;
        }
    }

/// <summary>
/// Method to get number of days to be added to the new transaction line Date
/// </summary>
/// <param name = "_rebateDate">TAMRebateDate table</param>
/// <param name = "_scanSupplierTransDate">Transaction date of custom Scan data</param>
/// <returns>number of days based on "Cumulate by" and "Rebate per" fields of Rebate date setup</returns>
protected Days getRebateToDate(TAMRebateDate  _rebateDate, TransDate  _scanSupplierTransDate)
{
    switch(_rebateDate.RebatePeriodCode)
    {
        case TAMRebatePeriodCode::Month:
            return dayOfMth(dateEndMth(_scanSupplierTransDate)) * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Week:
            return  METConstants::weekDays * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Year:
            return dayOfYr(dateEndYr(_scanSupplierTransDate)) * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Day:
        default:
            return METConstants::oneDay * _rebateDate.RebatePer;
    }
}

    /// <summary>
    /// Method to cretae Rebate source transaction
    /// </summary>
    /// <param name = "_rebateDateTrans">TAMRebateDateTrans table</param>
    /// <param name = "_rebateDate">TAMRebateDate table</param>
    /// <param name = "_scanSupplierData">METScanSupplierData table</param>
    /// <param name = "_toleranceQty">Tolerance quantity from user interface</param>
    /// <param name = "_rebateTableUnitId">Rebate table unit of measure</param>
    private void createTrans(TAMRebateDateTrans             _rebateDateTrans,
                             TAMRebateDate                  _rebateDate,
                             METRebateScanSupplierTable     _scanSupplierData,
                             Qty                            _toleranceQty,
                             UnitOfMeasureSymbol            _rebateTableUnitId)
    {
        TAMRebateTrans          rebateTrans;
        CustTable               custTableLoc;
        VendTable               vendTableLoc;
        InventDim               inventDimLoc;

        try
        {
            ttsbegin;
            rebateTrans.RebateRefAccount            =   _scanSupplierData.CustVendAccount;
            rebateTrans.RefCompanyId                =   _scanSupplierData.Company;
            rebateTrans.RebateRefDate               =   _scanSupplierData.TransactionDate;
            rebateTrans.ItemId                      =   _scanSupplierData.ItemId;
            rebateTrans.RefUnitId                   =   _rebateTableUnitId;
                        
            if(_scanSupplierData.CustVendACType == CustVendACType::Cust)
            {
                select firstonly InventSiteId, InventLocation
                    from custTableLoc index hint AccountIdx
                        where custTableLoc.AccountNum == _scanSupplierData.CustVendAccount;
                inventDimLoc.InventSiteId               =   custTableLoc.InventSiteId;
                inventDimLoc.InventLocationId           =   custTableLoc.InventLocation;
            }
            else
            {
                select firstonly InventSiteId, InventLocation
                    from vendTableLoc index hint AccountIdx
                        where vendTableLoc.AccountNum == _scanSupplierData.CustVendAccount;
                inventDimLoc.InventSiteId               =   vendTableLoc.InventSiteId;
                inventDimLoc.InventLocationId           =   vendTableLoc.InventLocation;
            }
            rebateTrans.InventDimId                 =   InventDim::findOrCreate(inventDimLoc).inventDimId;

            if (!_rebateTableUnitId || _rebateTableUnitId == _scanSupplierData.UnitOfMeasure)
            {
                rebateTrans.RebateQty               =   _scanSupplierData.RebateQty;
            }
            else
            {
                rebateTrans.RebateQty               =   EcoResProductUnitConverter::convertForReleasedProduct(rebateTrans.ItemId,
                                                                                                              rebateTrans.InventDimId,
                                                                                                              _scanSupplierData.RebateQty,
                                                                                                              this.findUnitOfMeasureRecId(_scanSupplierData.UnitOfMeasure),
                                                                                                              this.findUnitOfMeasureRecId(_rebateTableUnitId),
                                                                                                              NoYes::Yes);
            }

            rebateTrans.METScanSupplier             =   _scanSupplierData.IsScanSupplier;
            rebateTrans.METtoleranceQty             =   _toleranceQty;
            rebateTrans.RebateAmount                =   this.calcRebateAmount(rebateTrans.RebateQty, _rebateDate);
            rebateTrans.PostingAmount               =   rebateTrans.RebateAmount;
            rebateTrans.RebateTransId               =   _rebateDateTrans.RebateTransId;
            rebateTrans.RebateId                    =   _rebateDateTrans.RebateId;
            rebateTrans.CurrencyCode                =   _scanSupplierData.CurrencyCode;
            rebateTrans.METRebateScanSupplierTable  =   _scanSupplierData.RecId;
            rebateTrans.Claimed                     =   NoYes::Yes;

            if(rebateTrans.validateWrite())
            {
                rebateTrans.insert();

                METRebateScanSupplierTable  scanSupplierTable;
                select forupdate firstonly1 scanSupplierTable where scanSupplierTable.RecId == _scanSupplierData.RecId;
                scanSupplierTable.Processed = NoYes::Yes;
                if(scanSupplierTable.validateWrite())
                {
                    scanSupplierTable.update();
                }
            }
            ttscommit;
        }
        catch(Exception::Error)
        {
            Info("@MET:METRebateInsertError");
        }
    }

/// <summary>
/// Method to get the unit of measure Record Id
/// </summary>
/// <param name = "_unit">Unit symbol of measure</param>
/// <returns>Record Id of the Unit symbol</returns>
protected UnitOfMeasureRecId findUnitOfMeasureRecId(UnitOfMeasureSymbol _unit)
{
    UnitOfMeasureRecId unitOfMeasureRecId;
    if (unitCache.exists(_unit))
    {
        unitOfMeasureRecId = unitCache.lookup(_unit);
    }
    else
    {
        unitOfMeasureRecId = UnitOfMeasure::unitOfMeasureIdBySymbol(_unit);
        unitCache.insert(_unit, unitOfMeasureRecId);
    }

    return unitOfMeasureRecId;
}

    /// <summary>
    /// Method to calculate Rebate amount for Rebate source transaction
    /// </summary>
    /// <param name = "_rebateQty">Rebate quantity of source transaction line</param>
    /// <param name = "_rebateDate">TAMRebateData table</param>
    /// <returns>Calculate rebate amount</returns>
    protected Amount calcRebateAmount(Qty   _rebateQty, TAMRebateDate _rebateDate)
    {
        Amount          rebateAmt = 0;
        TAMRebateLine   rebateLine;

        while select rebateLine order by RebateFrom asc
            where rebateLine.RefLineNum == _rebateDate.LineNum && rebateLine.RebateId == _rebateDate.RebateId
               && rebateLine.RebateFrom <= _rebateQty
        {
            switch(rebateLine.RebateMethod)
            {
                case TAMRebateMethod::Fixed :
                    rebateAmt += rebateLine.RebateAmount;
                    break;
                case TAMRebateMethod::Percent :
                    break;
                case TAMRebateMethod::Rate :
                    rebateAmt += rebateLine.RebateAmount * _rebateQty;
                    break;
            }
        }
        return rebateAmt;
    }
